CREATE TABLE public.translations (key text NOT NULL, lang text NOT NULL CHECK (lang IN ('en','tl')), value text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (key, lang));
GRANT SELECT ON public.translations TO anon, authenticated;
GRANT ALL ON public.translations TO service_role;
ALTER TABLE public.translations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read translations" ON public.translations FOR SELECT TO anon, authenticated USING (true);
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS language text NOT NULL DEFAULT 'en' CHECK (language IN ('en','tl'));
